<script setup lang="ts">
const route=useRoute(), auth=useAdminApi(), config=useRuntimeConfig();
const section=computed(()=>String(route.params.section||''));
const loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),rows=ref<any[]>([]),permissions=ref<string[]>([]),roles=ref<any[]>([]),page=ref(1),totalPages=ref(1),unread=ref(0),filter=ref('');
const range=reactive({from:new Date(Date.now()-29*86400000).toISOString().slice(0,10),to:new Date().toISOString().slice(0,10),counselor_id:'',service_id:'',status:''});
const exportTypes=[['bookings','رزروها','appointments.manage'],['payments','پرداخت‌ها','finance.view'],['refunds','بازپرداخت‌ها','finance.view'],['settlements','تسویه‌ها','finance.view'],['counselor-earnings','درآمد مشاوران','finance.view'],['reception-performance','عملکرد پذیرش','appointments.manage'],['room-utilization','استفاده از اتاق‌ها','appointments.manage'],['capacity','ظرفیت','appointments.manage']];
const availableExports=computed(()=>exportTypes.filter(([, , permission])=>auth.can(permission)));
const title=computed(()=>({exports:'خروجی‌های Excel', 'admin-inbox':'مرکز اعلان مدیریت',roles:'نقش‌ها و مجوزها','content-media':'رسانه‌های CMS','payment-settings':'درگاه پرداخت','booking-settings':'سیاست‌های رزرو','audit-log':'رخدادهای مدیریتی'} as Record<string,string>)[section.value]||'مدیریت');
const gateways=ref<any[]>([]),activeGateway=ref(''),paymentReady=ref(false),policy=reactive<Record<string,string>>({});
const inboxDetail=ref<any>(null);
function message(e:any){const errors=e?.data?.errors;return errors?Object.values(errors).flat().join(' · '):e?.data?.message||'دریافت اطلاعات ناموفق بود.';}
function extract(r:any){return r?.data?.data||r?.data||[];}
function pages(r:any){return Number(r?.data?.last_page||r?.last_page||1);}
async function load(){loading.value=true;error.value='';try{
 if(section.value==='admin-inbox'){const q=new URLSearchParams({page:String(page.value),per_page:'30'});if(filter.value==='unread')q.set('unread','1');const r:any=await auth.request(`/admin/notifications?${q}`);rows.value=extract(r);totalPages.value=pages(r);unread.value=Number(r.unread_count||0);}
 else if(section.value==='roles'){const [r,p]:any[]=await Promise.all([auth.request('/admin/roles'),auth.request('/admin/permissions')]);roles.value=extract(r);permissions.value=extract(p);}
 else if(section.value==='content-media'){const q=new URLSearchParams({page:String(page.value),per_page:'24'});const r:any=await auth.request(`/admin/content-media?${q}`);rows.value=extract(r);totalPages.value=pages(r);}
 else if(section.value==='payment-settings'){const r:any=await auth.request<any>('/admin/booking/gateways');gateways.value=extract(r);activeGateway.value=r.active_provider||'';paymentReady.value=gateways.value.find((g:any)=>g.provider==='fake_bank')?.ready===true;}
 else if(section.value==='booking-settings'){const r:any=await auth.request<any>('/admin/booking/policy');Object.assign(policy,r.data||{});}
 else if(section.value==='audit-log'){const q=new URLSearchParams({page:String(page.value),per_page:'30'});if(filter.value)q.set('action',filter.value);const r:any=await auth.request(`/admin/audit-log?${q}`);rows.value=extract(r);totalPages.value=pages(r);}
}catch(e:any){error.value=message(e);}finally{loading.value=false;}}
async function markRead(row:any){busy.value=true;try{await auth.request(`/admin/notifications/${row.id}/read`,{method:'POST'});success.value='اعلان خوانده شد.';await load();}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function openInboxItem(row:any){busy.value=true;try{const r:any=await auth.request(`/admin/notifications/${row.id}`);inboxDetail.value=r.data||null;if(!row.read_at)await markRead(row);}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function readAll(){busy.value=true;try{await auth.request('/admin/notifications/read-all',{method:'POST'});success.value='اعلان‌های قابل مشاهده خوانده شدند.';await load();}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function download(type:string){if(busy.value)return;busy.value=true;error.value='';success.value='';try{const q=new URLSearchParams({from:range.from,to:range.to});for(const key of ['counselor_id','service_id','status'])if(range[key as keyof typeof range])q.set(key,range[key as keyof typeof range]);const token=auth.token.value;const response=await fetch(`${config.public.apiBase}/admin/booking/exports/${type}.xlsx?${q}`,{headers:{Accept:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',Authorization:`Bearer ${token}`}});if(!response.ok){let body:any;try{body=await response.json();}catch{}throw new Error(body?.message||`خطای دریافت فایل (${response.status})`);}const blob=await response.blob();if(!blob.size||!blob.type.includes('spreadsheetml'))throw new Error('پاسخ backend فایل XLSX معتبر نبود.');const disposition=response.headers.get('content-disposition')||'';const filename=disposition.match(/filename\*=UTF-8''([^;]+)|filename="?([^";]+)"?/i);const name=decodeURIComponent(filename?.[1]||filename?.[2]||`consulting-${type}-${range.from}-${range.to}.xlsx`);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);success.value=`فایل ${name} از backend دریافت شد.`;}catch(e:any){error.value=e?.message||message(e);}finally{busy.value=false;}}
const mediaPreview=ref('');
async function previewMedia(row:any){busy.value=true;try{const response=await fetch(`${config.public.apiBase}/admin/content-media/${row.id}/preview`,{headers:{Authorization:`Bearer ${auth.token.value}`}});if(!response.ok)throw new Error(`پیش‌نمایش رسانه دریافت نشد (${response.status}).`);mediaPreview.value=URL.createObjectURL(await response.blob());}catch(e:any){error.value=e?.message||message(e);}finally{busy.value=false;}}
async function removeMedia(row:any){if(!confirm('رسانه حذف شود؟ اگر در محتوای منتشرشده استفاده شده باشد، backend با خطای تعارض جلوگیری می‌کند.'))return;busy.value=true;try{await auth.request(`/admin/content-media/${row.id}`,{method:'DELETE'});success.value='رسانه حذف شد.';await load();}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
watch(mediaPreview,(next,prev)=>{if(prev)URL.revokeObjectURL(prev);});
const roleDialog=ref(false),editing=ref<any>(null),roleForm=reactive({name:'',label:'',permissions:[] as string[]});
function editRole(role?:any){editing.value=role||null;Object.assign(roleForm,{name:role?.name||'',label:role?.label||'',permissions:(role?.permissions||[]).map((p:any)=>p.permission)});roleDialog.value=true;}
async function saveRole(){if(busy.value)return;busy.value=true;try{if(editing.value)await auth.request(`/admin/roles/${editing.value.id}`,{method:'PATCH',body:{label:roleForm.label,permissions:roleForm.permissions}});else await auth.request('/admin/roles',{method:'POST',body:roleForm});roleDialog.value=false;success.value='نقش ذخیره شد.';await load();}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function activateFakeBank(){if(busy.value)return;busy.value=true;try{const r:any=await auth.request('/admin/booking/gateways',{method:'PUT',body:{active_provider:'fake_bank',enabled:true,mode:'sandbox'}});gateways.value=extract(r);activeGateway.value=r.active_provider||'';success.value='وضعیت Fake Bank از backend به‌روزرسانی شد.';}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function savePolicy(){if(busy.value)return;busy.value=true;try{const body=Object.fromEntries(Object.entries(policy).map(([k,v])=>[k,k==='cancellation_penalty_basis'?v:Number(v)]));const r:any=await auth.request('/admin/booking/policy',{method:'PUT',body});Object.assign(policy,r.data||{});success.value='سیاست رزرو ذخیره شد.';}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function deleteRole(role:any){if(!confirm(`نقش «${role.label}» حذف شود؟ نقش‌های سیستمی یا تخصیص‌یافته از سمت backend قابل حذف نیستند.`))return;busy.value=true;try{await auth.request(`/admin/roles/${role.id}`,{method:'DELETE'});success.value='نقش حذف شد.';await load();}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
watch([section,page,filter],load);onMounted(load);
</script>

<template>
 <main dir="rtl" class="admin-page">
  <header class="admin-page__header"><div><div class="admin-eyebrow">عملیات مدیریت</div><h1>{{title}}</h1><p v-if="section==='exports'">گزارش‌ها مستقیماً به‌صورت XLSX توسط backend ساخته می‌شوند؛ دادهٔ جدول مرورگر به فایل تبدیل نمی‌شود.</p><p v-else-if="section==='admin-inbox'">اعلان‌ها براساس مجوزهای کاربر از سمت backend محدود شده‌اند.</p><p v-else-if="section==='roles'">مدیریت نقش فقط برای Super Admin مجاز است؛ تغییر مجوزها نشست کاربران مرتبط را باطل می‌کند.</p><p v-else>فهرست رسانه‌های خصوصی CMS؛ پیش‌نمایش برای مدیر دارای مجوز قابل دسترسی است.</p></div><v-btn v-if="section==='roles'&&auth.user.value?.is_admin" color="primary" prepend-icon="mdi-plus" @click="editRole()">نقش جدید</v-btn><v-btn v-if="section==='admin-inbox'" variant="tonal" :disabled="busy||!unread" @click="readAll">خواندن همه ({{unread}})</v-btn><v-btn variant="tonal" prepend-icon="mdi-refresh" :loading="loading" @click="load">به‌روزرسانی</v-btn></header>
  <v-alert v-if="error" type="error" variant="tonal" class="mb-4" closable @click:close="error=''">{{error}}</v-alert><v-alert v-if="success" type="success" variant="tonal" class="mb-4" closable @click:close="success=''">{{success}}</v-alert>
  <template v-if="section==='exports'"><v-card class="pa-4 mb-4"><v-row><v-col cols="12" md="4"><v-text-field v-model="range.from" type="date" label="از تاریخ (تهران)"/></v-col><v-col cols="12" md="4"><v-text-field v-model="range.to" type="date" label="تا تاریخ (تهران)"/></v-col><v-col cols="12" md="4"><v-text-field v-model="range.counselor_id" type="number" label="شناسه مشاور (اختیاری)"/></v-col><v-col cols="12" md="6"><v-text-field v-model="range.service_id" type="number" label="شناسه خدمت (اختیاری)"/></v-col><v-col cols="12" md="6"><v-text-field v-model="range.status" label="وضعیت (اختیاری)" hint="مقادیر معتبر را backend اعتبارسنجی می‌کند."/></v-col></v-row><v-alert type="info" variant="tonal">گزارش ظرفیت محاسبهٔ تجمیعی backend است و محدودیت مدل زمان‌بندی آن را دارد. ظرفیت تضمین‌کنندهٔ slot آزاد نیست.</v-alert></v-card><v-row><v-col v-for="[type,label,permission] in availableExports" :key="type" cols="12" sm="6" lg="3"><v-card class="pa-4 h-100"><div class="text-h6 mb-2">{{label}}</div><p class="text-medium-emphasis">خروجی XLSX سرور با بازه و فیلترهای بالا</p><v-btn color="primary" block :loading="busy" :disabled="busy||!range.from||!range.to||range.to<range.from" @click="download(type)">دریافت Excel</v-btn></v-card></v-col></v-row></template>
  <template v-else-if="section==='payment-settings'"><v-alert type="warning" variant="tonal" class="mb-4">درگاه‌های واقعی فعال نیستند. Fake Bank فقط ابزار محلی/آزمایشی backend است و این صفحه درگاه واقعی را فعال نمی‌کند.</v-alert><v-row><v-col v-for="gateway in gateways" :key="gateway.provider" cols="12" md="4"><v-card class="pa-5 h-100"><div class="d-flex justify-space-between"><h2>{{gateway.label||gateway.provider}}</h2><v-chip :color="gateway.active?'success':gateway.ready?'info':'default'">{{gateway.active?'فعال':gateway.ready?'آماده برای تست':'غیرفعال'}}</v-chip></div><p>Provider: {{gateway.provider}}</p><p>پیاده‌سازی: {{gateway.implemented?'موجود':'نیازمند قرارداد/provider'}}</p><p>حالت: {{gateway.mode||'—'}}</p><ul v-if="gateway.missing_configuration?.length"><li v-for="missing in gateway.missing_configuration" :key="missing">{{missing}}</li></ul><v-btn v-if="gateway.provider==='fake_bank'&&gateway.ready&&auth.can('finance.manage')&&!gateway.active" color="primary" :loading="busy" @click="activateFakeBank">فعال‌سازی Fake Bank آزمایشی</v-btn></v-card></v-col></v-row></template>
  <template v-else-if="section==='booking-settings'"><v-alert type="info" variant="tonal" class="mb-4">مقادیر سیاست از backend می‌آیند؛ تغییراتی که با رزروهای موجود تعارض داشته باشند از سمت سرور رد می‌شوند.</v-alert><v-card class="pa-5"><v-row><v-col v-for="[key,label] in [['cancellation_penalty_percent','درصد جریمه لغو'],['cancellation_cutoff_hours','مهلت لغو (ساعت)'],['reschedule_cutoff_hours','مهلت جابه‌جایی (ساعت)'],['max_client_reschedules','حداکثر جابه‌جایی مراجع'],['hold_minutes','مدت نگهداری رزرو (دقیقه)'],['connection_release_minutes','زمان انتشار لینک جلسه پیش از شروع (دقیقه)']]" :key="key" cols="12" md="6"><v-text-field v-model="policy[key]" type="number" :label="label"/></v-col></v-row><v-select v-model="policy.cancellation_penalty_basis" :items="[{title:'بر مبنای مبلغ پرداخت‌شده',value:'paid'},{title:'بر مبنای کل مبلغ',value:'total'}]" label="مبنای جریمه"/><v-btn v-if="auth.can('finance.manage')" color="primary" :loading="busy" @click="savePolicy">ذخیره سیاست</v-btn><v-alert v-else type="info">برای تغییر این تنظیمات مجوز finance.manage لازم است.</v-alert></v-card></template>
  <template v-else-if="section==='admin-inbox'"><v-select v-model="filter" class="max-width-300" :items="[{title:'همه اعلان‌ها',value:''},{title:'فقط خوانده‌نشده',value:'unread'}]" label="فیلتر"/><v-card class="admin-table-card"><div class="admin-table-scroll"><v-table><thead><tr><th>عنوان</th><th>جزئیات</th><th>رویداد</th><th>مجوز</th><th>زمان</th><th>وضعیت</th><th></th></tr></thead><tbody><tr v-for="n in rows" :key="n.id"><td>{{n.title||n.subject||'اعلان'}}</td><td>{{n.message||n.body||n.description||'—'}}</td><td>{{n.event}}</td><td>{{n.permission}}</td><td>{{n.created_at}}</td><td>{{n.read_at?'خوانده‌شده':'جدید'}}</td><td><v-btn size="small" variant="text" :disabled="busy" @click="openInboxItem(n)">جزئیات</v-btn><v-btn v-if="!n.read_at" size="small" :disabled="busy" @click="markRead(n)">خواندم</v-btn></td></tr><tr v-if="!loading&&!rows.length"><td colspan="7"><div class="admin-empty-state">اعلانی برای این فیلتر وجود ندارد.</div></td></tr></tbody></v-table></div><div v-if="totalPages>1" class="admin-table-pagination"><v-btn :disabled="page<=1" @click="page--">قبلی</v-btn><span>صفحه {{page}} از {{totalPages}}</span><v-btn :disabled="page>=totalPages" @click="page++">بعدی</v-btn></div></v-card></template>
  <template v-else-if="section==='audit-log'"><v-text-field v-model="filter" label="فیلتر رخداد/عبارت" clearable class="max-width-500"/><v-card class="admin-table-card"><div class="admin-table-scroll"><v-table><thead><tr><th>کاربر</th><th>عملیات</th><th>رزرو</th><th>جزئیات</th><th>زمان</th></tr></thead><tbody><tr v-for="entry in rows" :key="entry.id"><td>{{entry.actor_name||entry.actor_id||'سامانه'}}</td><td>{{entry.action}}</td><td>{{entry.booking_id||'—'}}</td><td><code>{{entry.details}}</code></td><td>{{entry.created_at}}</td></tr><tr v-if="!loading&&!rows.length"><td colspan="5">رخدادی وجود ندارد.</td></tr></tbody></v-table></div><div v-if="totalPages>1" class="admin-table-pagination"><v-btn :disabled="page<=1" @click="page--">قبلی</v-btn><span>صفحه {{page}} از {{totalPages}}</span><v-btn :disabled="page>=totalPages" @click="page++">بعدی</v-btn></div></v-card></template>
  <template v-else-if="section==='roles'"><v-alert v-if="!auth.user.value?.is_admin" type="error" variant="tonal" class="mb-4">تعریف و ویرایش نقش‌ها فقط برای Super Admin مجاز است.</v-alert><v-card class="admin-table-card"><div class="admin-table-scroll"><v-table><thead><tr><th>نام</th><th>برچسب</th><th>مجوزها</th><th>نوع</th><th>اقدام</th></tr></thead><tbody><tr v-for="r in roles" :key="r.id"><td>{{r.name}}</td><td>{{r.label}}</td><td>{{(r.permissions||[]).map((p:any)=>p.permission).join('، ')||'بدون مجوز'}}</td><td>{{r.is_assignable?'قابل تخصیص':'سیستمی'}}</td><td><v-btn v-if="auth.user.value?.is_admin" size="small" @click="editRole(r)">ویرایش</v-btn><v-btn v-if="auth.user.value?.is_admin" size="small" color="error" @click="deleteRole(r)">حذف</v-btn></td></tr><tr v-if="!loading&&!roles.length"><td colspan="5">نقشی یافت نشد.</td></tr></tbody></v-table></div></v-card></template>
  <template v-else><v-row><v-col v-for="m in rows" :key="m.id" cols="12" sm="6" lg="3"><v-card><div class="d-flex align-center justify-center bg-grey-lighten-4" style="height:140px"><v-icon size="48">{{m.mime_type?.startsWith('image/')?'mdi-image':'mdi-file'}}</v-icon></div><v-card-title>{{m.original_name||`رسانه #${m.id}`}}</v-card-title><v-card-subtitle>{{m.mime_type}} · {{m.size}} bytes</v-card-subtitle><v-card-actions><v-btn :disabled="!m.mime_type?.startsWith('image/')" @click="previewMedia(m)">پیش‌نمایش امن</v-btn><v-spacer/><v-btn color="error" @click="removeMedia(m)">حذف امن</v-btn></v-card-actions></v-card></v-col><v-col v-if="!loading&&!rows.length" cols="12"><div class="admin-empty-state">رسانه‌ای ثبت نشده است.</div></v-col></v-row></template>
  <v-dialog :model-value="!!mediaPreview" max-width="900" @update:model-value="v=>{if(!v){URL.revokeObjectURL(mediaPreview);mediaPreview=''}}"><v-card class="pa-3"><v-img :src="mediaPreview" max-height="75vh" contain/><v-card-actions><v-spacer/><v-btn @click="URL.revokeObjectURL(mediaPreview);mediaPreview=''">بستن</v-btn></v-card-actions></v-card></v-dialog>
  <v-dialog :model-value="!!inboxDetail" max-width="700" @update:model-value="v=>{if(!v)inboxDetail=null}"><v-card v-if="inboxDetail" class="pa-5" dir="rtl"><h2>{{inboxDetail.title||inboxDetail.subject||'اعلان'}}</h2><p class="my-3">{{inboxDetail.message||inboxDetail.body||inboxDetail.description||'—'}}</p><v-divider class="my-3"/><div>رویداد: {{inboxDetail.event}} · مجوز: {{inboxDetail.permission}} · زمان: {{inboxDetail.created_at}}</div><pre class="mt-3">{{JSON.stringify(inboxDetail.payload||{},null,2)}}</pre><v-btn class="mt-3" @click="inboxDetail=null">بستن</v-btn></v-card></v-dialog>
  <v-dialog v-model="roleDialog" max-width="750"><v-card class="pa-5" dir="rtl"><h2 class="mb-4">{{editing?'ویرایش نقش':'ایجاد نقش'}}</h2><v-text-field v-if="!editing" v-model="roleForm.name" label="شناسه انگلیسی نقش (lowercase)"/><v-text-field v-model="roleForm.label" label="نام نمایشی"/><v-select v-model="roleForm.permissions" :items="permissions" label="مجوزها" multiple chips/><div class="d-flex ga-2"><v-btn color="primary" :loading="busy" :disabled="!roleForm.label||(!editing&&!roleForm.name)||!auth.user.value?.is_admin" @click="saveRole">ذخیره</v-btn><v-btn variant="text" @click="roleDialog=false">انصراف</v-btn></div></v-card></v-dialog>
 </main>
</template>
